import{_ as e}from"./chunks/neiruha.D3XV6UDq.js";import{_ as t,c as r,a0 as i,o as s}from"./chunks/framework.p2VkXzrt.js";const o="/assets/02-yazyki-01.DT6gA2B-.jpg",l="/assets/02-yazyki-02.Biwc7jTV.jpg",n="/assets/speaker.Calay2kK.png",g=JSON.parse('{"title":"Открытие №2. Языки","description":"","frontmatter":{},"headers":[],"relativePath":"slides/02-yazyki.md","filePath":"slides/02-yazyki.md"}'),h={name:"slides/02-yazyki.md"};function c(d,a,p,u,m,b){return s(),r("div",null,a[0]||(a[0]=[i('<h1 id="открытие-no2-языки" tabindex="-1">Открытие №2. Языки <a class="header-anchor" href="#открытие-no2-языки" aria-label="Permalink to &quot;Открытие №2. Языки&quot;">​</a></h1><p><strong>Вопрос:</strong><br> Как ускорить понимание и изучение информации на другом языке, который я плохо знаю?</p><hr><h2 id="цитата-для-вдохновения" tabindex="-1">Цитата для вдохновения <a class="header-anchor" href="#цитата-для-вдохновения" aria-label="Permalink to &quot;Цитата для вдохновения&quot;">​</a></h2><blockquote><p>&quot;Тот, кто не знает других языков, не знает ничего о своем.&quot;<br> — Иоганн Вольфганг фон Гёте</p></blockquote><hr><div class="image-row"><img src="'+o+'" alt="Системы дубляжа в действии" class="thumb"><img src="'+l+'" alt="Whisper от OpenAI работает с аудио" class="thumb"></div><hr><h2 id="история-развития" tabindex="-1">История развития <a class="header-anchor" href="#история-развития" aria-label="Permalink to &quot;История развития&quot;">​</a></h2><ul><li><strong>Раньше:</strong> Переводы и изучение языка были сложны и требовали много времени.</li><li><strong>Сегодня:</strong><ul><li>Системы дубляжа (например, Yandex, Heygen, ElevenLabs) переводят не только слова, но и интонацию.</li><li>Whisper от OpenAI может превращать аудио в эмбеддинги, независимо от языка. Это потрясающе!</li><li>ИИ может говорить на любом языке, а также легко вовлекать тебя в общение на новом для тебя языке. Я даже поговорил на китайском 10 секунд впервые.</li></ul></li></ul><hr><h2 id="личная-история" tabindex="-1">Личная история <a class="header-anchor" href="#личная-история" aria-label="Permalink to &quot;Личная история&quot;">​</a></h2><p>Я всегда хотел понимать больше: больше языков, больше культур, больше знаний. Благодаря технологиям я смог:</p><ul><li>Усваивать сложные лекции и материалы на английском языке, которые раньше пугали. Также по работе я постоянно сталкивался с немецким и итальянским.</li><li>Улучшить свои знания через многократное прослушивание дублированных видео, необходимых мне для роста.</li><li>Ощутить, что слушать языки — становится бесконечным удовольствием, страдание побеждено.</li></ul><hr><h2 id="инсаит" tabindex="-1">Инсайт <a class="header-anchor" href="#инсаит" aria-label="Permalink to &quot;Инсайт&quot;">​</a></h2><blockquote> &quot;Ребенок естественно выучивает свой первый язык, находясь в правильной среде. Он не старается его учить. Whisper и другие технологии показали мне, что язык — больше не преграда, дверь открыта. Векторные эмбеддинги доказали: мысль гораздо глубже, чем слова, она универсальна.&quot; </blockquote><hr><h2 id="практическии-вывод" tabindex="-1">Практический вывод <a class="header-anchor" href="#практическии-вывод" aria-label="Permalink to &quot;Практический вывод&quot;">​</a></h2><div class="practical-tip"><img src="'+n+'" alt="Иконка динамика" class="tip-icon"><p> Больше не надо изучать языки. Изучай мир! Слушай дубляж, погружайся в культуру. Твори на той территории, где раньше было сложно или невозможно. <strong>Технологии пришли к тебе на помощь.</strong></p></div><hr><h2 id="ключевая-идея" tabindex="-1">Ключевая идея <a class="header-anchor" href="#ключевая-идея" aria-label="Permalink to &quot;Ключевая идея&quot;">​</a></h2><p>Языковые технологии не только переводят, но и понимают нас. Whisper и другие системы (например аудио-модель GPT-4o) помогают устранить барьеры, чтобы мы могли сосредоточиться на главном — общении.</p><hr><div class="neiruha-comment"><img src="'+e+'" alt="Нейруха" class="neiruha-avatar"><p> *(улыбается с хитринкой)* Я знаю, что ты хотел бы выучить французский или итальянский. С системами дубляжа это стало так просто, что у тебя больше нет оправданий! </p></div>',25)]))}const _=t(h,[["render",c]]);export{g as __pageData,_ as default};
